<template>
  <div>
    <div class="row q-my-sm">
      <div class="col">
        {{ $t('show_tab_index') }}
        <q-icon name="help_outline" class="help-sign cursor-pointer">
          <q-tooltip
            ><div>{{ $t('show_tab_index_help') }}</div></q-tooltip
          >
        </q-icon>
      </div>
      <div class="col-auto">
        <q-checkbox v-model="showTabIndex" />
      </div>
    </div>

    <div class="form-builder-settings">
      <template v-for="(element, index) in fields" :key="index">
        <div class="row q-my-sm">
          <div class="col">
            {{ $t(element.translation_key) }}
            <q-icon
              v-if="element.has_help"
              name="help_outline"
              @click="scrollToHelpSection(element.help_id)"
              class="help-sign cursor-pointer"
            >
              <q-tooltip>
                <div>{{ $t(element.help_tooltip_translation_key) }}</div>
              </q-tooltip>
            </q-icon>
          </div>
          <div class="col-auto">
            <component
              outlined
              :is="element.type"
              :field-name="element.name"
              v-model="settings[element.name]"
            />
          </div>
        </div>
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { fields } from './fields-def';
import helpUtil from 'src/help/helpUtil';
import { QCheckbox, QInput } from 'quasar';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import {
  useFormBuilderSettingsStore,
  useFormBuilderStore,
} from 'src/store/main';

export default defineComponent({
  name: 'Properties',
  mixins: [helperUtil, helpUtil],
  components: {
    QCheckbox,
    QInput,
  },
  data() {
    return {
      fields: fields,
    };
  },
  methods: {},
  setup() {
    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { settings } = storeToRefs(form_builder_settings_store);

    const form_builder_store = useFormBuilderStore();
    const { showTabIndex } = storeToRefs(form_builder_store);

    return {
      showTabIndex,
      settings,
    };
  },
});
</script>

<style lang="scss">
.form-builder-settings .q-field__control {
  height: 32px;
}
</style>
