<template>
  <div class="text-capitalize full-width">{{ $t('auto_accounting') }}</div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useFormBuilderStore } from 'src/store/main';

export default defineComponent({
  name: 'AutoAccountingSection',
  props: {
    currentField: {
      type: Object,
      default: () => ({}),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: ['inputClicked', 'inputValueChanges', 'updateModel'],
  beforeMount() {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode } = storeToRefs(form_builder_store);
    return { isFormBuilderMode };
  },
});
</script>
