<template>
  <div class="full-width" v-if="filteredFields.length > 0">
    <draggable
      :list="filteredFields"
      class="dragArea row"
      :group="{ name: 'formbuilder', pull: 'clone', put: false }"
      :sort="false"
      item-key="name"
    >
      <template v-for="(element, index) in filteredFields" :key="index">
        <div class="fb-left-panel-item">
          <Icon v-if="element.icon && element.icon.startsWith('mdi:')" :icon="element.icon" width="18" height="18" />
          <img v-else :src="element.icon" width="18" />
          <span>{{ element.text }}</span>
        </div>
      </template>
    </draggable>
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { FormBuilder } from './formbuilder.js';
import { useFormBuilderStore } from 'src/store/main';
import { VueDraggableNext } from 'vue-draggable-next';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
// import _ from 'lodash'

export default defineComponent({
  name: 'Elements',
  components: {
    
    draggable: VueDraggableNext,
  },
  props: {
    isApproval: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    const formBuilderData = FormBuilder.data();
    return {
      tables: ref(formBuilderData.tables),
      dropElementOptions: formBuilderData.dropElementOptions,
    };
  },
  computed: {
    fields(): any[] {
      const formBuilderData = FormBuilder.data();
      return this.isApproval
        ? formBuilderData.approvalFields
        : formBuilderData.fields;
    },
  },
  watch: {
    isApproval: {
      immediate: false,
      handler() {
        this.refreshFilteredFields();
      },
    },
  },
  mounted() {
    this.init();
  },
  methods: {
    init() {
      this.prepareTables();
      this.refreshFilteredFields();
    },
    refreshFilteredFields() {
      this.filteredFields = this.fields.filter((field: any) => {
        return (
          field.hide_in_panel_list == false ||
          field.hide_in_panel_list == undefined
        );
      });
    },
    async prepareTables() {
      const docType = this.$route.params.doc_type as string;

      await this.getDocumentTables(String(this.$route.params.doc_type));

      for (let [tbl_name, tbl] of Object.entries(this.documentTables)) {
        this.tables[0].name = tbl_name;
        this.tables[0].text = 'Table (' + tbl_name + ')';

        if (docType == 'INVOICE') {
          this.tables[0].fieldType = formBuilderInputTypes.LINE_ITEM_TABLE;
        }
        // this.fields.push(JSON.parse(JSON.stringify(this.tables[0])));

        //save table names
        this.documentTableNames.push(tbl_name);
      }

      // loop through tables array  add each object to fields array except the first one
      // Array.from(this.tables).forEach((table: any, index:number) => {
      //   if (index == 0) return;
      //   this.fields.push(JSON.parse(JSON.stringify(table)));
      // });
    },
    // clone(field : any) {
    //   return _.cloneDeep(field);
    // },
    checkStopDragCondition(field: any) {
      // logInfo('======================================');
      // logInfo(field);
      // var form = this.forms,
      //   formArray = [];
      // for (var key in form) {
      //   formArray.push(form[key]['fieldType'])
      // }
      // // Check if the fieldname exist in formArray
      // // And when the field.isUnique too
      // return _.includes(formArray, field.name) && field.isUnique;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { documentTables, documentTableNames } =
      storeToRefs(form_builder_store);

    const { getDocumentTables } = form_builder_store;
    return {
      documentTables,
      documentTableNames,

      //functions
      getDocumentTables,
      filteredFields: ref([] as dynamicObj[]),
    };
  },
});
</script>

