<template>
  <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md text-primary">
    Columns Settings
  </div>

  <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
    <q-select
      outlined
      v-model="
        formBuilderConfigModel[activeFieldName].columns[columnIndex]
          .tr_ocr_model_id
      "
      :options="model_list"
      :label="
        'KI Model' +
        ' (' +
        formBuilderConfigModel[activeFieldName].columns[columnIndex].name +
        ')'
      "
      dense
      emit-value
      map-options
      @update:model-value="
        onColumnUpdateTROCRModel(
          formBuilderConfigModel[activeFieldName].columns[columnIndex].col_id,
          formBuilderConfigModel[activeFieldName].columns[columnIndex]
            .tr_ocr_model_id,
        )
      "
    />
  </div>

  <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
    <q-select
      outlined
      v-model="
        formBuilderConfigModel[activeFieldName].columns[columnIndex]
          .list_of_values
      "
      :options="lov_list"
      :label="
        'list Of values' +
        ' (' +
        formBuilderConfigModel[activeFieldName].columns[columnIndex].name +
        ')'
      "
      dense
      emit-value
      map-options
    />
  </div>

  <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
    <f-toggle
      size="xs"
      v-model="
        formBuilderConfigModel[activeFieldName].columns[columnIndex]
          .run_script_on_change
      "
      val="md"
      :label="
        $t('run_script_on_change') +
        ' (' +
        formBuilderConfigModel[activeFieldName].columns[columnIndex].name +
        ')'
      "
      class="q-mt-sm"
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { $ } from 'src/pages/assets';
import { defineComponent, ref } from 'vue';
import {
  useFormBuilderStore,
  useDropdownStore,
  useFieldValuesSettingsStore,
} from 'src/store/main';

export default defineComponent({
  name: 'PropertiesOfTableOfCheckboxes',

  props: {
    columnIndex: {
      type: Number,
      default: 0,
    },
  },
  data() {
    return {};
  },

  methods: {
    onColumnUpdateTROCRModel(colId: string, model: string) {
      const fieldElement = $('#col_' + colId) as HTMLElement;

      if (fieldElement) {
        if (model) {
          fieldElement.classList.add('text-primary');
        } else {
          fieldElement.classList.remove('text-primary');
        }
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formLayout,
      activeFieldName,
      formBuilderModel,
      formBuilderConfigModel,
    } = storeToRefs(form_builder_store);

    const dropdown_store = useDropdownStore();
    const { model_list } = storeToRefs(dropdown_store);

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { lov_list } = storeToRefs(field_values_setting_store);

    return {
      lov_list,
      model_list,
      formLayout,
      activeFieldName,
      formBuilderModel,
      formBuilderConfigModel,
    };
  },
});
</script>

<style lang="scss" scoped></style>
