<!--vbase-->
<template>
  <div class="fb-canvas-toolbar">
    <div class="fb-canvas-toolbar__left">
      <template v-if="!isReadOnly">
        <q-btn flat dense round icon="add_circle_outline" size="sm" class="fb-icon-muted" @click="addGroup()">
          <q-tooltip>{{ $t('create_group') }}</q-tooltip>
        </q-btn>
        <q-btn flat dense round icon="data_object" size="sm" class="fb-icon-muted" @click="showJsonForm = true" v-if="!isPanelSection">
          <q-tooltip>{{ $t('create_group_by_json') }}</q-tooltip>
        </q-btn>
      </template>
    </div>
    <div class="fb-canvas-toolbar__right">
      <f-toggle
        size="xs"
        v-model="isExtenedPanel"
        v-if="isPanelSection"
      >
        <q-tooltip>{{ $t('deactivate') }}</q-tooltip>
      </f-toggle>
    </div>
  </div>

  <div :key="reRenderGroupForm" ref="fieldsContainer" :class="isPanelSection ? '' : 'form-builder-middle-section-height scrolle-y'" :id="isPanelSection ? 'field_scrolle_2' : 'field_scrolle'">
    <div class="full-width">
      <template v-for="(groupObj, groupIndex) in formLayout" :key="`div-${groupIndex}-${groupObj.id}`" >
        <div :id="`div-${groupIndex}`" :ref="`group-${groupIndex}`" class="section-block dashed-border q-mb-md q-pa-sm display-inline-block"
          :class=" getElementBorder(groupObj) + ' ' + (hoveredGroupIndex === groupIndex && !isPanelSection ? 'opacity-half' : '') "
          @dragover.prevent="onDragOver(Number(groupIndex))"
          @drop="onDrop($event, Number(groupIndex))"
          @dragleave="onDragLeave"
          v-if="groupObj.is_panel_section_group == null || groupObj.is_panel_section_group === isPanelSection"
          :style="'width:' + getElementWidth(groupObj, true) + '%'"
        >
          <div class="q-pt-sm q-pb-sm">
            <div class="row" :class="{ 'cursor-move': !isReadOnly }" v-if="!isPanelSection">
              <div class="q-pr-sm" style="flex: 1; min-width: 0;">
                <q-input
                  outlined
                  dense
                  v-model="groupObj.title"
                  :label="$t('group_title')"
                  :readonly="isReadOnly"
                  @click="inputClicked(getGroupKey(groupObj.name))"
                />
              </div>
              <div class="fb-group-actions">
                <q-btn flat dense round icon="content_copy" size="sm" class="fb-icon-muted" @click="copyGroupJson($event, Number(groupIndex))">
                  <q-tooltip>{{ $t('copy_group_json') }}</q-tooltip>
                </q-btn>
                <template v-if="!isReadOnly">
                  <q-btn flat dense round icon="arrow_downward" size="sm" class="fb-icon-muted" @click="moveGroupDown($event, Number(groupIndex))">
                    <q-tooltip>{{ $t('move_down') }}</q-tooltip>
                  </q-btn>
                  <q-btn flat dense round icon="arrow_upward" size="sm" class="fb-icon-muted" @click="moveGroupUp($event, Number(groupIndex))">
                    <q-tooltip>{{ $t('move_up') }}</q-tooltip>
                  </q-btn>
                  <q-btn flat dense round icon="delete_outline" size="sm" class="fb-icon-muted" @click="deleteSection(Number(groupIndex))">
                    <q-tooltip>{{ $t('delete_group') }}</q-tooltip>
                  </q-btn>
                  <q-icon
                    name="drag_indicator"
                    class="cursor-grab fb-drag-handle fb-icon-muted"
                    size="20px"
                    draggable="true"
                    @dragstart="onDragStart($event, Number(groupIndex))"
                  >
                    <q-tooltip>{{ $t('drag') }}</q-tooltip>
                  </q-icon>
                </template>
              </div>
            </div>
            <div class="fb-group-actions" v-else>
              <q-btn flat dense round icon="settings" size="sm" class="fb-icon-muted" @click="inputClicked(getGroupKey(groupObj.name))">
                <q-tooltip>{{ $t('settings') }}</q-tooltip>
              </q-btn>
              <q-btn v-if="!isReadOnly" flat dense round icon="delete_outline" size="sm" class="fb-icon-muted" @click="deleteSection(Number(groupIndex))">
                <q-tooltip>{{ $t('delete_group') }}</q-tooltip>
              </q-btn>
            </div>
          </div>
          <div class="full-width meta" v-if="isDefaultFieldLoaded">
            <draggable
              v-model="groupObj.rows"
              class="dragArea"
              item-key="name"
              v-bind="dragOptions"
              ghost-class="sortable__ghost"
              @change="itemAdded($event, Number(groupIndex))"
            >
              <template v-for="(element, index) in groupObj.rows" :key="index">
                <div
                  v-if="element"
                  @click="inputClicked(element.name)"
                  class="element_parent q-pa-sm"
                  :style="'width:' + getElementWidth(element) + '%'"
                  :class="
                    (element.name == activeFieldName
                      ? 'is--active rounded-lg border border-primary bg-card shadow-sm'
                      : ' ') +
                    (isPanelSection ? ' ' : ' display-block') +
                    (element.tr_ocr_model_id ? ' text-primary ' : ' ') +
                    (isReadOnly ? ' ' : ' cursor-move')
                  "
                >
                  <!-- <label class="form__label" v-model="form.label" v-show="form.hasOwnProperty('label')">{{ form.label }}</label> -->
                  <component
                    :is="element.fieldType"
                    :currentField="element"
                    :isReadOnly="isReadOnly"
                    :fieldName="element.name"
                    :groupIndex="groupIndex"
                    :itemIndex="index"
                    @itemAdded="itemAdded"
                    @removeField="removeField"
                    @inputClicked="inputClicked"
                    @inputValueChanges="inputValueChanges"
                    @updateModel="updateModel"
                    @applyFuzzySearch="applyFuzzySearch"
                    @markTableColumns="markTableColumns"
                    v-if="renderComponent"
                  >
                  </component>

                  <div
                    class="full-width q-pa-xs height-24"
                    v-if="element.name === activeFieldName && element.fieldType !== SUB_GROUP && !isReadOnly"
                  >
                    <q-btn
                      round
                      color="primary"
                      icon="table_rows"
                      size="xs"
                      class="h-m-5"
                      @click="addTableRow(element.name)"
                      v-if="element.fieldType === TABLE_OF_CHECKBOXES"
                    >
                      <q-tooltip>{{ $t('add_row') }}</q-tooltip>
                    </q-btn>
                    <q-btn
                      round
                      color="primary"
                      icon="view_column"
                      size="xs"
                      class="h-m-5"
                      @click="addTableColumn(element.name)"
                      v-if="element.fieldType === TABLE_OF_CHECKBOXES && false"
                    >
                      <q-tooltip>{{ $t('add_column') }}</q-tooltip>
                    </q-btn>
                    <q-btn
                      flat
                      dense
                      class="float-right delete-ele"
                      @click="removeField($event, Number(groupIndex))"
                    >
                      <Icon icon="mdi:delete-outline" class="size-4" />
                      <q-tooltip>{{ $t('delete') }}</q-tooltip>
                    </q-btn>
                  </div>
                </div>
              </template>
            </draggable>
          </div>
        </div>
      </template>
    </div>
  </div>

  <q-dialog v-model="showJsonForm">
    <q-card class="width-800">
      <q-toolbar class="secondary-toolbar text-white">
        <q-toolbar-title>{{ $t('edit_json') }}</q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <div class="row">
          <div class="col-sm-12 col-md-12 col-lg-12">
            <div class="row">
              <div class="col-sm-12 col-md-12 col-lg-12">
                <!-- <q-input outlined v-model="strFormLayout" type="textarea" /> -->
                <LayoutJsonEditor ref="layoutJsonEditor" :jsonData="{}" />
              </div>
              <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
                <q-btn
                  :label="$t('save')"
                  @click="savePastedJson()"
                  color="primary"
                  icon="done"
                  v-close-popup
                />
              </div>
            </div>
          </div>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { uid, copyToClipboard } from 'quasar';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { useFormBuilderStore } from 'src/store/main';
import { VueDraggableNext } from 'vue-draggable-next';
import Label from './form_elements/FormElementLabel.vue';
import SubGroup from 'src/formBuilder/FormDropAbleArea.vue';
import LayoutJsonEditor from 'src/components/JsonEditor.vue';
import LovInput from './form_elements/FormElementLovInput.vue';
import CheckBox from './form_elements/FormElementCheckBox.vue';
import ExportButton from './form_elements/FormElementButton.vue';
import TextInput from './form_elements/FormElementTextInput.vue';
import EnumInput from './form_elements/FormElementEnumInput.vue';
import UserDropdown from './form_elements/FormElementUserDropdown.vue';
import GroupDropdown from './form_elements/FormElementGroupDropdown.vue';
import MultiCheckBox from './form_elements/FormElementMultiCheckBox.vue';
import PoMatchButton from './form_elements/ButtonFormElements/PoMatch.vue';
import { FormBuilder } from 'src/formBuilder/form_elements/formbuilder.js';
import { isDocTypeInvoice, GROUP_NAMES, CONSTANTS } from 'src/constants';
import AmountButtonsPanel from './form_elements/FormElementAmountFields.vue';
import SaveRulesButton from './form_elements/ButtonFormElements/SaveRules.vue';
import RejectDocument from './form_elements/ButtonFormElements/RejectDocument.vue';
import AutoAccountingButton from './form_elements/ButtonFormElements/AutoAccounting.vue';
import ExportWithoutValidation from './form_elements/ButtonFormElements/ExportWithoutValidation.vue';

import LineItemTable from 'src/pages/TableExtraction/LineItemTable.vue';
import TableOfCheckboxes from './form_elements/FormElemenTableOfCheckboxes.vue';
import VertexPanel from 'src/formBuilder/form_elements/FormElementVertexPanel.vue';
import HorizontalSeparator from './form_elements/FormElementHorizontalSeparator.vue';
import InvoiceButtons from 'src/formBuilder/form_elements/FormElementInvoiceButtons.vue';
import QRCodeExtractedFields from './form_elements/FormElementQRCodeExtractedFields.vue';
import AditionalAmountButtonsPanel from './form_elements/FormElementAdditionalAmountFields.vue';
import ExtractedTableTabPanels from 'src/formBuilder/form_elements/FormElementExtractedTableTabPanels.vue';
import ApprovalExtractedTableTabPanels from 'src/formBuilder/form_elements/approval/FormElementExtractedTableTabPanels.vue';
import Notes from './form_elements/approval/FormElementNotes.vue';
import { notify } from 'src/components/notifications/notify';
import Button from './form_elements/approval/FormElementApprovalButton.vue';
import SecondApprover from './form_elements/approval/FormElementSecondApprover.vue';
import CorrectionButtons from './form_elements/approval/ChargesCorrectionButtons.vue';
import DocumentApprover from './form_elements/approval/FormElementDocumentApprover.vue';
import AutoAccountingSection from './form_elements/approval/FormElementAutoAccounting.vue';
import QuoteCompareLines from 'src/pages/Settings/Components/Approval/LineItemApprovalTableQuote.vue';
import { formBuilderInputTypes, allowAbleModels, tableBodyRows, FORM_BUILDER_CONSTANTS} from 'src/formBuilder/formBuilderConstants';
import displayFieldLabel from 'src/utils/displayFieldLabel';

// [DOCB-13727] Props that feed displayFieldLabel/getFieldLabel.
// Refreshed from the current Field Settings whenever a placed field is
// registered, so the layout JSON snapshot can never pin a stale label.
const LABEL_SOURCE_KEYS = [
  'field_label',
  'title',
  'translation_key',
  'alt_label',
  'hide_label',
];

export default defineComponent({
  el: 'fields_designer',
  mixins: [helperMixin],
  emits: [
    'showConnectionFromField',
    'saveTemplate',
    'markTableColumns',
    'clearCanvas',
  ],
  props: {
    isPanelSection: {
      type: Boolean,
      default: false,
    },
    // main.vue never sets it; layout.vue passes true for system layouts.
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  beforeCreate() {
    if (this.$route.params.layout_type) {
      this.$options.components!.ExtractedTableTabPanels = ApprovalExtractedTableTabPanels;
    }
  },
  computed: {
    // vue-draggable-next declares no `disabled` prop, so whatever we pass lands
    // on its root div as a plain attribute — and Quasar fades `[disabled] *`
    // regardless of the value, which greyed out every field for `disabled=false`.
    // So the key is only present when it is actually on.
    dragOptions(): Record<string, any> {
      return {
        group: {
          name: 'formbuilder',
          pull: !this.isReadOnly,
          put: !this.isReadOnly,
        },
        sort: !this.isReadOnly,
        ...(this.isReadOnly ? { disabled: true } : {}),
      };
    },
  },
  data() {
    return {
      showJsonForm: ref(false),
      hoveredGroupIndex: ref(null as any),
      draggingGroupIndex: ref(null as any),
      SUB_GROUP: formBuilderInputTypes.SUB_GROUP,
      TABLE_OF_CHECKBOXES: formBuilderInputTypes.TABLE_OF_CHECKBOXES,
      CORRECTION_BUTTONS: ref(FormBuilder.data().CORRECTION_BUTTONS),
    };
  },
  components: {
    
    Label,
    SubGroup,
    CheckBox,
    LovInput,
    TextInput,
    EnumInput,
    UserDropdown,
    ExportButton,
    MultiCheckBox,
    LineItemTable,
    GroupDropdown,
    TableOfCheckboxes,
    AmountButtonsPanel,
    HorizontalSeparator,
    AditionalAmountButtonsPanel,
    ExtractedTableTabPanels,
    VertexPanel,
    PoMatchButton,
    SaveRulesButton,
    InvoiceButtons,
    RejectDocument,
    LayoutJsonEditor,
    AutoAccountingButton,
    QRCodeExtractedFields,
    ExportWithoutValidation,
    Notes,
    Button,
    DocumentApprover,
    SecondApprover,
    CorrectionButtons,
    AutoAccountingSection,
    QuoteCompareLines,
    draggable: VueDraggableNext,
  },
  mounted: function () {
    document.addEventListener('element_click', this.triggerFieldFocus);

    const scrollAreaElRef = this.$refs['fieldsContainer'];
    const scrollArea = Array.isArray(scrollAreaElRef)
      ? scrollAreaElRef[0]
      : scrollAreaElRef;
    if (scrollArea) {
      scrollArea.addEventListener('dragover', this.autoScrollWhileDragging);
    }
  },
  unmounted: function () {
    document.removeEventListener('element_click', this.triggerFieldFocus);

    const scrollAreaElRef = this.$refs['fieldsContainer'];
    const scrollArea = Array.isArray(scrollAreaElRef)
      ? scrollAreaElRef[0]
      : scrollAreaElRef;
    if (scrollArea) {
      scrollArea.removeEventListener('dragover', this.autoScrollWhileDragging);
    }
  },
  methods: {
    itemAdded(e: any, index: number) {
      this.onDragLeave();
      // only execute for add case
      if (!e.added || !e.added.element) {
        return;
      }

      let newSection = JSON.parse(JSON.stringify(e.added.element));
      if (newSection.fieldType == this.SUB_GROUP) {
        this.activeFieldName = newSection.name;
        this.updateModel(newSection);
        this.keyToUpdateComponnets++;
        return;
      }

      if (!newSection.hasOwnProperty('rows')) {
        if (!this.formBuilderConfigModel[newSection.name]) {
          this.updateModel(newSection);
          this.handleTabIndexChange(newSection.name);
        }
        this.keyToUpdateComponnets++;
        return;
      }
      // check for duplicate groups
      const groupAlreadyExists = this.formLayout.some(
        (group: any) => group.name === newSection.name,
      );

      if (groupAlreadyExists) {
        this.cleanJson(index);
        notify.error(this.$t('group_with_same_name_exists'));
        return;
      }

      newSection.elementWidth = 100;
      newSection.is_stcky_group = false;
      newSection.right_border = this.isPanelSection ? true : false;
      newSection.bottom_border = this.isPanelSection ? true : false;
      newSection.is_panel_section_group = this.isPanelSection;

      let newSectionRows = [] as any;

      newSection.rows.forEach((row: any, sectionIndex: any) => {
        row.forEach((subRow: any, subRowIndex: any) => {
          if (newSection.name == GROUP_NAMES.charges) {
            subRow.elementWidth = 43;
          } else {
            subRow.elementWidth = this.calculateRowColSize(row.length);
          }
          newSectionRows.push(subRow);

          if (
            newSection.name == GROUP_NAMES.charges &&
            (sectionIndex + 1) % 2 == 0
          ) {
            this.addCorrectionButtons(newSectionRows);
          }
        });
      });

      // If number of rows in charges group is odd, add last buttons
      if (
        newSection.name == GROUP_NAMES.charges &&
        newSection.rows.length % 2 != 0
      ) {
        this.addCorrectionButtons(newSectionRows);
      }

      newSection.rows = [];
      newSection.rows = newSectionRows;

      if (
        isDocTypeInvoice(this.docType) &&
        newSection.name == GROUP_NAMES.tax_details
      ) {
        this.filterFieldsForInvoices(newSection);
        this.adjustFieldsForInvoices(newSection);
      }

      // cleaup newly added object
      this.cleanJson(index);

      if (this.formLayout[index].rows.length > 0) {
        this.formLayout.splice(index, 0, newSection);
        this.keyToUpdateComponnets ++;
        return;
      }
      this.formLayout[index] = newSection;
      this.keyToUpdateComponnets ++;
    },
    cleanJson(index: number) {
      const indexsToRemove: number[] = [];

      this.formLayout[index].rows.forEach((row: any, index: any) => {
        if (row.hasOwnProperty('rows')) {
          indexsToRemove.push(index);
        }
      });

      if (indexsToRemove.length > 0) {
        indexsToRemove.reverse();
        for (let itemIndex of indexsToRemove) {
          this.formLayout[index].rows.splice(itemIndex, 1);
        }
      }
    },
    filterFieldsForInvoices(newSection: any) {
      for (let [index, row] of newSection.rows.entries()) {
        if (FORM_BUILDER_CONSTANTS.amountGroup1.includes(row.field_name)) {
          newSection.rows.splice(
            index,
            0,
            FormBuilder.data().AMOUNT_BUTTONS_PANEL,
          );
          break;
        }
      }

      for (let [index, row] of newSection.rows.entries()) {
        if (
          FORM_BUILDER_CONSTANTS.aditionalAmountFields.includes(row.field_name)
        ) {
          newSection.rows.splice(
            index,
            0,
            FormBuilder.data().ADITIONAL_AMOUNT_BUTTONS_PANEL,
          );
          break;
        }
      }
    },
    adjustFieldsForInvoices(newSection: any) {
      for (let [index, row] of newSection.rows.entries()) {
        if (FORM_BUILDER_CONSTANTS.amountPanelField.includes(row.field_name)) {
          row.elementWidth = Math.round(
            this.calculateRowColSize(
              FORM_BUILDER_CONSTANTS.amountGroup1.length,
            ),
          );
          continue;
        }

        if (
          FORM_BUILDER_CONSTANTS.aditionalAmountFields.includes(row.field_name)
        ) {
          row.elementWidth = Math.round(
            this.calculateRowColSize(
              FORM_BUILDER_CONSTANTS.additionalAmountInRow,
            ),
          );
          continue;
        }
      }
    },
    calculateRowColSize(rowSize: number) {
      if (rowSize > 1) {
        return 100 / rowSize;
      }
      return 100;
    },
    addCorrectionButtons(newSectionRows: any) {
      let correctionElement = JSON.parse(
        JSON.stringify(this.CORRECTION_BUTTONS),
      );
      correctionElement.elementWidth = 14;
      correctionElement.name = 'button_' + uid();
      newSectionRows.push(correctionElement);
    },

    addGroup() {
      const group = {
        fieldType: formBuilderInputTypes.GROUP,
        name: 'group_' + uid(),
        title: '',
        group_key: '',
        is_panel_section_group: this.isPanelSection,
        elementWidth: 100,
        // 'height': 100,
        right_border: this.isPanelSection ? true : false,
        bottom_border: this.isPanelSection ? true : false,
        is_stcky_group: false,
        short_cut_key_1: '',
        short_cut_key_2: '',
        rows: [],
      };

      this.formLayout.push(group);
      this.formBuilderConfigModel[group.name] = group;
    },
    deleteSection(groupIndex: number) {
      this.activeTab = 'form_elements';
      this.activeFieldName = '';

      this.$nextTick(function () {
        this.formLayout.splice(groupIndex, 1);
        this.reRenderGroupForm++;
      });
    },
    moveGroupUp(e: any, groupIndex: number) {
      if (groupIndex == 0) {
        return;
      }
      const insertOn = groupIndex - 1;
      const item = JSON.parse(JSON.stringify(this.formLayout[groupIndex]));
      this.formLayout.splice(groupIndex, 1);
      this.formLayout.splice(insertOn, 0, item);
      this.reRenderGroupForm++;

      this.$nextTick(function () {
        let elementId = 'div-' + insertOn;
        document.getElementById(elementId)!.scrollIntoView();
      });
    },
    moveGroupDown(e: any, groupIndex: number) {
      if (this.formLayout.length == groupIndex) {
        return;
      }
      const insertOn = groupIndex + 1;
      const item = JSON.parse(JSON.stringify(this.formLayout[groupIndex]));
      this.formLayout.splice(groupIndex, 1);
      this.formLayout.splice(groupIndex + 1, 0, item);
      this.reRenderGroupForm++;

      this.$nextTick(function () {
        let elementId = 'div-' + insertOn;
        document.getElementById(elementId)!.scrollIntoView();
      });
    },
    copyGroupJson(e: any, groupIndex: number) {
      copyToClipboard(JSON.stringify(this.formLayout[groupIndex])).then(() => {
        notify.success('Copied!');
      });
    },
    savePastedJson() {
      const strJson = (this.$refs.layoutJsonEditor as any).getJson();
      if (!strJson) {
        return;
      }
      const group = JSON.parse(strJson);
      if (Object.entries(group).length == 0) {
        return;
      }

      // check for duplicate groups
      const groupAlreadyExists = this.formLayout.some(
        (groupItem: any) => groupItem.name === group.name,
      );

      if (groupAlreadyExists) {
        notify.error(this.$t('group_with_same_name_exists'));
        return;
      }

      this.formLayout.push(group);
      this.formBuilderConfigModel[this.getGroupKey(group.name)] = group;

      this.$nextTick(function () {
        setTimeout(() => {
          (this.$refs.fieldsContainer as any).scrollTop = (
            this.$refs.fieldsContainer as any
          ).scrollHeight;
        });
      });
    },

    removeField(
      e: any,
      groupIndex: number,
      subGroupIndex: number | null = null,
    ) {
      e.stopPropagation();
      if (
        this.formBuilderConfigModel[this.activeFieldName] &&
        this.formBuilderConfigModel[this.activeFieldName].isDefaultField
      ) {
        // this.defaultFields.push(this.formBuilderConfigModel[this.activeFieldName]);
        for (let field of this.defaultFields) {
          if (field.name === this.activeFieldName) {
            field.isAlreadyAdded = false;
            break;
          }
        }
      }

      if (subGroupIndex || subGroupIndex == 0) {
        this.formLayout[groupIndex].rows[subGroupIndex].rows = this.formLayout[
          groupIndex
        ].rows[subGroupIndex].rows.filter(
          (item: any) => item.name !== this.activeFieldName,
        );
      } else {
        this.formLayout[groupIndex].rows = this.formLayout[
          groupIndex
        ].rows.filter((item: any) => item.name !== this.activeFieldName);
      }
      this.removeChildElements(
        this.formBuilderConfigModel[this.activeFieldName],
      );

      let isFieldFound = false;

      // TODO need to handel the sub group
      exit_loops: for (let [index, group] of this.formLayout.entries()) {
        for (let row of group.rows) {
          if (row.name == this.activeFieldName) {
            isFieldFound = true;
            break exit_loops;
          }
        }
      }

      if (!isFieldFound) {
        delete this.formBuilderConfigModel[this.activeFieldName];
        delete this.formBuilderModel[this.activeFieldName];
      }

      this.activeFieldName = '';
      this.activeTab = 'form_elements';

      this.$emit('clearCanvas');
    },

    removeChildElements(FieldDef: any) {
      try {
        if (
          !FieldDef.hasOwnProperty('child_elements') ||
          !Array.isArray(FieldDef.child_elements)
        ) {
          return;
        }
        for (let [key, def] of Object.entries(FieldDef.child_elements)) {
          const childDef = def as dynamicObj;
          delete this.formBuilderConfigModel[childDef.name];
          delete this.formBuilderModel[childDef.name];
        }
      } catch (error) {
        logError(error);
      }
    },

    getElementBorder(element: any) {
      let border = '';
      if (this.formBuilderConfigModel.hasOwnProperty(element.name)) {
        border = this.formBuilderConfigModel[element.name].right_border
          ? ' border-right'
          : '';

        border += this.formBuilderConfigModel[element.name].bottom_border
          ? ' border-bottom'
          : '';

        return border;
      }
      border = element.right_border ? ' border-right' : '';

      border += element.bottom_border ? ' border-bottom' : '';

      return border;
    },

    triggerFieldFocus(e: any) {
      this.inputClicked(e.detail);
    },

    inputClicked(fieldName: string) {
      this.activeTab = 'element_properties';
      const fieldConfig = this.formBuilderConfigModel[fieldName];
      if (!fieldConfig) {
        this.activeFieldName = '';
        return;
      }
      this.activeFieldName = fieldName;

      if (formBuilderInputTypes.TABLE_OF_CHECKBOXES === fieldConfig.fieldType || formBuilderInputTypes.EXPORT_BUTTON === fieldConfig.fieldType) {
        return;
      }
      this.setTrOcrModeld(fieldName);

      if (this.allowAreaSelection) {
        this.showConnectionFromField(fieldName);
      }
    },
    setTrOcrModeld(fieldName: string) {
      if (
        !this.formBuilderConfigModel[fieldName].hasOwnProperty(
          'tr_ocr_model_id',
        )
      ) {
        this.formBuilderConfigModel[fieldName].tr_ocr_model_id = '';
      }
    },
    inputValueChanges(fieldName: string, fieldType: string) {
      if (formBuilderInputTypes.TABLE_OF_CHECKBOXES === fieldType) {
        this.$emit('showConnectionFromField', fieldName);
      } else if ('checkbox' === fieldType) {
        this.inputClicked(fieldName);
      }

      setTimeout(() => {
        this.formBuilderModel[fieldName].formatted_value = false;
      }, 50);

      return;
    },

    updateModel(newField: any, isChildElement = false) {
      if (this.formBuilderConfigModel.hasOwnProperty(newField.name)) {
        return;
      }
      this.formBuilderConfigModel[newField.name] = JSON.parse(
        JSON.stringify(newField),
      );

      // Apply isHidden from Field Settings (defaultFields) for all field types
      const defaultField = this.defaultFields.find(
        (f: any) => f.field_name === newField.field_name || f.field_name === newField.name
      );
      if (defaultField && defaultField.isHidden !== undefined) {
        this.formBuilderConfigModel[newField.name].isHidden = defaultField.isHidden;
      }

      // [DOCB-13727] The layout JSON stores a full snapshot of the field taken
      // when it was placed, so a rename in Field Settings kept showing the old
      // label until the field was removed and re-added. Re-resolve the
      // label-bearing props from the current Field Settings (defaultFields);
      // layout props (elementWidth, coords, tabIndex, position) stay with the
      // stored snapshot.
      if (defaultField) {
        const config = this.formBuilderConfigModel[newField.name];
        for (const key of LABEL_SOURCE_KEYS) {
          if (defaultField[key] !== undefined) {
            config[key] = defaultField[key];
          } else {
            delete config[key];
          }
        }
        config.label = displayFieldLabel.methods.getFieldLabel(
          config,
          '',
        );

        // The canvas renders each placed field from the formLayout row, not
        // from formBuilderConfigModel — and on layout load the components
        // emit updateModel with the LIVE row object. Refreshing only the
        // config model made the new label appear after the next save
        // round-trip, while the open builder kept showing the stored
        // snapshot (Markus' reopen on DOCB-13727). Write the resolved label
        // props back onto the row so the rename is visible immediately.
        for (const key of LABEL_SOURCE_KEYS) {
          if (defaultField[key] !== undefined) {
            newField[key] = defaultField[key];
          } else {
            delete newField[key];
          }
        }
        newField.label = config.label;
      }

      if (newField.fieldType === formBuilderInputTypes.HORIZONTAL_SEPARATOR) {
        if (
          !newField.hasOwnProperty('space_from_top') &&
          !newField.hasOwnProperty('space_from_bottom')
        ) {
          this.formBuilderConfigModel[newField.name].space_from_top = 'q-mt-lg';
          this.formBuilderConfigModel[newField.name].space_from_bottom = '';
        }

        if (
          !this.formBuilderConfigModel[newField.name].hasOwnProperty('color')
        ) {
          this.formBuilderConfigModel[newField.name]['color'] =
            CONSTANTS.default_separator_color;
        }

        if (
          !this.formBuilderConfigModel[newField.name].hasOwnProperty('size')
        ) {
          this.formBuilderConfigModel[newField.name]['size'] = 2;
        }
      }

      if (newField.fieldType === formBuilderInputTypes.EXTRACTED_TABLE) {
        this.formBuilderModel[newField.name] = JSON.parse(
          JSON.stringify(newField),
        );
      }

      if (newField.fieldType === formBuilderInputTypes.AI_EXTRACTED_TABLE) {
        this.formBuilderModel[newField.name] = JSON.parse(
          JSON.stringify(newField),
        );
      }

      if (newField.fieldType === formBuilderInputTypes.TABLE_OF_CHECKBOXES) {
        this.formBuilderConfigModel[newField.name].tableBodyRows.forEach(
          (tableBodyRow: any, bodyRowsIndex: any) => {
            tableBodyRow.forEach(
              (tableBodyColumn: any, bodyColumnIndex: any) => {
                if (!tableBodyColumn.hasOwnProperty('field_group')) {
                  tableBodyColumn['field_group'] = '';
                }

                if (!tableBodyColumn.hasOwnProperty('field_threshold')) {
                  tableBodyColumn['field_threshold'] = '';
                }

                if (!tableBodyColumn.hasOwnProperty('run_script_on_change')) {
                  tableBodyColumn['run_script_on_change'] = false;
                }

                if (!tableBodyColumn.hasOwnProperty('tabIndex')) {
                  tableBodyColumn['tabIndex'] = 0;
                }

                this.formBuilderModel[tableBodyColumn.name] = JSON.parse(
                  JSON.stringify(tableBodyColumn),
                );
                this.formBuilderConfigModel[tableBodyColumn.name] = JSON.parse(
                  JSON.stringify(tableBodyColumn),
                );
              },
            );
          },
        );
        return;
      }

      this.formBuilderModel[newField.name] = [];
      this.formBuilderModel[newField.name].page = '';
      this.formBuilderModel[newField.name].color = '';
      this.formBuilderModel[newField.name].score = '';
      this.formBuilderModel[newField.name].coords = [];
      this.formBuilderModel[newField.name].confidence = '';

      if (newField.fieldType === formBuilderInputTypes.MULTI_CHECK_BOX) {
        this.formBuilderModel[newField.name].groupList = [];
        this.formBuilderModel[newField.name].value = '';
        this.formBuilderModel[newField.name].formatted_value = '';
      } else if (newField.fieldType === formBuilderInputTypes.CHECK_BOX) {
        this.formBuilderModel[newField.name].value = false;
        this.formBuilderModel[newField.name].formatted_value = false;

        if (
          !this.formBuilderConfigModel[newField.name].hasOwnProperty(
            'field_group',
          )
        ) {
          this.formBuilderConfigModel[newField.name]['field_group'] = '';
        }

        if (
          !this.formBuilderConfigModel[newField.name].hasOwnProperty(
            'field_threshold',
          )
        ) {
          this.formBuilderConfigModel[newField.name]['field_threshold'] = '';
        }

        if (
          !this.formBuilderConfigModel[newField.name].hasOwnProperty(
            'run_script_on_change',
          )
        ) {
          this.formBuilderConfigModel[newField.name]['run_script_on_change'] =
            false;
        }

        if (
          !this.formBuilderConfigModel[newField.name].hasOwnProperty('tabIndex')
        ) {
          this.formBuilderConfigModel[newField.name]['tabIndex'] = 0;
        }
      } else {
        this.formBuilderModel[newField.name].value = '';
        this.formBuilderModel[newField.name].formatted_value = '';

        this.formBuilderConfigModel[newField.name].is_textarea = this
          .formBuilderConfigModel[newField.name].is_textarea
          ? true
          : false;
        this.formBuilderConfigModel[newField.name].run_script_on_change = this
          .formBuilderConfigModel[newField.name].run_script_on_change
          ? true
          : false;
        this.formBuilderConfigModel[newField.name].run_workflow_on_change = this
          .formBuilderConfigModel[newField.name].run_workflow_on_change
          ? true
          : false;
      }

      if (
        !this.formBuilderConfigModel[newField.name].hasOwnProperty('tabIndex')
      ) {
        this.formBuilderConfigModel[newField.name].tabIndex = 0;
      }

      if (newField.isDefaultField) {
        for (let field of this.defaultFields) {
          if (field.name === newField.name) {
            field.isAlreadyAdded = true;
            break;
          }
        }
      }
      if (isChildElement) {
        return;
      }
      this.renderChildElements(newField.name);
      this.activeFieldName = newField.name;
    },
    applyFuzzySearch(field: any) {
      return null;
    },
    markTableColumns(columnId: string) {
      this.$emit('markTableColumns', columnId);
    },
    showConnectionFromField(connectionId: string) {
      if (
        !allowAbleModels.includes(
          this.formBuilderConfigModel[connectionId].fieldType,
        )
      ) {
        return;
      }
      this.$emit('showConnectionFromField', connectionId);
    },
    addTableRow(fieldName: string) {
      let tempTableBodyRow = JSON.parse(JSON.stringify(tableBodyRows));
      for (let column of tempTableBodyRow) {
        column.name = 'checkbox_' + uid();
        // column.oldName = column.name;
        column.formatted_value = false;
        column.value = false;
        column.fieldType = formBuilderInputTypes.CHECK_BOX;

        this.formBuilderConfigModel[column.name] = [];
        this.formBuilderConfigModel[column.name] = JSON.parse(
          JSON.stringify(column),
        );

        this.formBuilderModel[column.name] = [];
        this.formBuilderModel[column.name].page = '';
        this.formBuilderModel[column.name].color = '';
        this.formBuilderModel[column.name].score = '';
        this.formBuilderModel[column.name].coords = [];
        this.formBuilderModel[column.name].value = false;
        this.formBuilderModel[column.name].confidence = '';
        this.formBuilderModel[column.name].formatted_value = false;
      }

      this.formBuilderConfigModel[fieldName].tableBodyRows.push(
        tempTableBodyRow,
      );
    },
    addTableColumn(fieldName: string) {
      for (let row of this.formBuilderConfigModel[fieldName].tableBodyRows) {
        let newColumn = {
          isLabelArea: false,
          isDisabled: false,
          name: uid(),
        };
        row.push(newColumn);
      }

      for (let row of this.formBuilderConfigModel[fieldName].tableHeaderRows) {
        row.push('C');
      }
    },
    onDragStart(event: any, index: number) {
      this.draggingGroupIndex = index;

      event.dataTransfer.setData('text/plain', index);
      event.dataTransfer.setData('source', 'drag-icon');

      this.$nextTick(() => {
        const groupElRef = this.$refs[`group-${index}`];
        const groupEl = Array.isArray(groupElRef) ? groupElRef[0] : groupElRef;

        if (!groupEl || !event) return;

        // Clone the real DOM
        const clone = groupEl.cloneNode(true);
        const rect = groupEl.getBoundingClientRect();

        // Fix width/height from original group
        clone.style.width = rect.width + 'px';
        clone.style.height = rect.height + 'px';
        clone.style.position = 'absolute';
        clone.style.top = '0';
        clone.style.left = '0';
        clone.style.zIndex = '9999';
        clone.style.pointerEvents = 'none';
        clone.style.opacity = '1';
        clone.style.boxSizing = 'border-box';

        // Avoid transform scale issues
        clone.style.transform = 'scale(1)';

        document.body.appendChild(clone);

        // ⚠ Use the mouse pointer offset inside the group
        const offsetX = event.clientX - rect.left;
        const offsetY = event.clientY - rect.top;

        // ✅ Use actual offset under mouse
        event.dataTransfer.setDragImage(clone, offsetX, offsetY);

        // Clean up after next frame
        setTimeout(() => {
          document.body.removeChild(clone);
        }, 0);
      });
    },
    onDrop(event: any, index: number) {
      const source = event.dataTransfer.getData('source');
      if (source !== 'drag-icon') {
        this.onDragLeave();
        return; // Ignore drop not started from drag icon
      }
      if (this.draggingGroupIndex === null || this.draggingGroupIndex === index)
        return;
      const dragged = this.formLayout.splice(this.draggingGroupIndex, 1)[0];
      this.formLayout.splice(index, 0, dragged);
      this.draggingGroupIndex = null;
      this.hoveredGroupIndex = null;
    },
    onDragOver(index: number) {
      this.hoveredGroupIndex = index;
    },
    onDragLeave() {
      this.hoveredGroupIndex = null;
    },
    autoScrollWhileDragging(e: any) {
      const scrollAreaElRef = this.$refs['fieldsContainer'];
      const scrollArea = Array.isArray(scrollAreaElRef)
        ? scrollAreaElRef[0]
        : scrollAreaElRef;

      const rect = scrollArea.getBoundingClientRect();
      const edgeSize = 80; // px range from top/bottom to start scrolling
      const speed = 10; // px per dragover event

      if (e.clientY < rect.top + edgeSize) {
        // Scroll up
        scrollArea.scrollTop -= speed;
      } else if (e.clientY > rect.bottom - edgeSize) {
        // Scroll down
        scrollArea.scrollTop += speed;
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      docType,
      showImages,
      activeTab,
      formLayout,
      defaultFields,
      formBuilderModel,
      formBuilderConfigModel,
      activeFieldName,
      keyToUpdateComponnets,
      renderComponent,
      formLayoutImages,
      isExtenedPanel,
      allowAreaSelection,
      isDefaultFieldLoaded,
      reRenderGroupForm,
      isSaving,
    } = storeToRefs(form_builder_store);

    const {
      getElementWidth,
      renderChildElements,
      handleTabIndexChange,
      getGroupKey,
    } = form_builder_store;

    return {
      docType,
      activeTab,
      showImages,
      formLayout,
      defaultFields,
      activeFieldName,
      renderComponent,
      formBuilderModel,
      formLayoutImages,
      reRenderGroupForm,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      formBuilderConfigModel,
      allowAreaSelection,
      isExtenedPanel,
      isSaving,

      // funcations
      getGroupKey,
      getElementWidth,
      renderChildElements,
      handleTabIndexChange,
    };
  },
});
</script>

