<template>
  <div class="full-width">
    <q-input
      v-model="searchInput"
      class="q-pt-md q-pb-md"
      dense
      autofocus
      :label="$t('search')"
      outlined
    />
  </div>
  <div class="full-width">
    <draggable
      :list="filteredFields"
      class="dragArea row"
      :group="{ name: 'formbuilder', pull: 'clone', put: false }"
      :sort="false"
      item-key="name"
    >
      <template
        v-for="(element, index) in filteredFields"
        :key="index + '_' + element.field_name"
      >
        <div
          class="fb-left-panel-item"
          :class="element.is_hidden ? 'hidden-field' : ''"
        >
          <div class="fb-left-panel-item__icon">
            <Icon v-if="element.icon && element.icon.startsWith('mdi:')" :icon="element.icon" width="18" height="18" :class="element.is_hidden ? 'icon-grayed' : ''" />
            <img v-else :src="element.icon" width="18" :class="element.is_hidden ? 'icon-grayed' : ''" />
          </div>
          <div class="fb-left-panel-item__text">
            <div :class="element.is_hidden ? 'text-grey-6' : ''">
              {{ element.label }}
              <q-icon
                v-if="element.is_hidden"
                name="visibility_off"
                size="xs"
                color="grey-6"
                class="q-ml-xs"
              >
                <q-tooltip>{{ $t('field_is_hidden') }}</q-tooltip>
              </q-icon>
            </div>
            <div class="text-grey-6" style="font-size: 11px;">
              {{ element.field_name }}
            </div>
          </div>
        </div>
      </template>
    </draggable>
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { useFormBuilderStore } from 'src/store/main';
import { VueDraggableNext } from 'vue-draggable-next';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'DefaultElements',
  mixins: [helperMixin, displayFieldLabel],
  components: {
    
    draggable: VueDraggableNext,
  },
  data() {
    return {
      searchInput: '',
      filteredFields: [] as any, // Directly managed list of displayable fields
    };
  },
  watch: {
    searchInput() {
      this.updateFilteredFields(); // Recalculate list when search input changes
    },
    defaultFields: {
      handler() {
        this.updateFilteredFields(); // Recalculate list when defaultFields changes
      },
      deep: true,
    },
  },
  methods: {
    async init() {
      this.hideLoading();
      try {
        await this.loadDocumentDefaultFields(
          this.$route.params.doc_type as string,
        );
        this.isDefaultFieldLoaded = true;
        this.updateFilteredFields(); // Initialize the filtered list on load
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    updateFilteredFields() {
      this.filteredFields = this.defaultFields.filter(
        (field: any) =>
          (field &&
            // Hidden fields are now INCLUDED (not filtered out)
            (this.searchInput === '' ||
              field.label
                .toLowerCase()
                .includes(this.searchInput.toLowerCase()) ||
              field.name
                .toLowerCase()
                .includes(this.searchInput.toLowerCase())) &&
            !field.isAlreadyAdded) as boolean,
      );
    },
  },
  mounted() {
    this.init();
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { defaultFields, isDefaultFieldLoaded } =
      storeToRefs(form_builder_store);
    const { loadDocumentDefaultFields } = form_builder_store;

    return {
      defaultFields,
      isDefaultFieldLoaded,
      loadDocumentDefaultFields,
    };
  },
});
</script>

