<!--vbase-->
<template>
  <div class="full-width full-height q-pa-lg">
    <div
      class="drag-area text-center full-width full-height dashed-border-2px"
      style="padding: 20px"
      @drop="drop"
      @dragover="allowDrop"
      @dragleave="dragLeave"
    >
      <div class="">
        <Icon icon="mdi:export" width="64" height="64" aria-hidden="true" />
        <div style="padding: 20px">{{ $t('land_dragndrop') }}</div>
        <!--      <q-btn for="file-upload" style='width: 130px' color='primary' label='BROWSE' />-->
        <q-file
          style="width: 200px !important; margin: auto; white-space: nowrap"
          color="white"
          data-cy="upload-multiple-docs"
          label-color="white"
          bg-color="primary"
          filled
          @update:model-value="uploadFile"
          v-model="uploadedFiles"
          :label="$t('upload')"
        >
          <template v-slot:prepend>
            <q-icon name="attachment" color="white" />
          </template>
          <template v-slot:file="{ index, file }">
            <div class="text-white">
              {{ file.name }}
            </div>
            <q-tooltip>
              {{ file.name }}
            </q-tooltip>
            <span v-if="false"> {{ index }} </span>
          </template>
        </q-file>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';

import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { useFormBuilderStore } from 'src/store/main';
import { api, getAuthorizationToken } from 'pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { notify } from 'src/components/notifications/notify';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  
  emits: ['saveTemplate', 'loadImage'],
  props: [
    // 'navigateTo',
    'showSpinner',
  ],
  data() {
    return {};
  },
  methods: {
    uploadFile(value: any) {
      // let file = e.target.files || e.dataTransfer.files;
      this.uploadedFiles = value;
      let file = this.uploadedFiles;
      if (!file) {
        notify.error(this.$t('NO_FILE_SELECTED'));
      }
      this.uploadFilee(file);
    },
    allowDrop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.add('bg-grey-5');
      event.currentTarget.classList.add('bd-shadow');
    },
    drop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');

      this.uploadFilee(event.dataTransfer.files[0]);
    },
    dragLeave(event: any) {
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
    },
    async uploadFilee(file: any) {
      this.uploadedFiles = null;

      if (file.type !== 'application/pdf') {
        notify.error(this.$t('ONLY_PDF_ALLOWED'));
        return;
      }
      this.showLoading();

      let templateId = (this.$route.query.id as string) || (this.$route.params.id as string);
      if (!templateId) {
        notify.error(this.$t('TEMPLATE_ID_IS_MANDATORY'));
        this.hideLoading();
        return;
      }

      let formData = new FormData();
      formData.append('id', templateId);
      formData.append('file', file);
      formData.append('org_id', getOrgId());

      let invoice_response: any;
      try {
        let token: string = await getAuthorizationToken();
        invoice_response = await axios.post(
          api.upload_template_sample,
          formData,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
              Authorization: token,
            },
          },
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return;
      } finally {
        this.hideLoading();
      }

      this.formLayoutImages = [];
      this.formLayoutImages = invoice_response.data.images;
      this.proximityTokens = invoice_response.data.proximity_tokens;
      this.showImages = true;
      this.$emit('loadImage', 0, true);
      this.$emit('saveTemplate', true);
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { showImages, formLayoutImages, proximityTokens } =
      storeToRefs(form_builder_store);

    return {
      showImages,
      proximityTokens,
      formLayoutImages,
      uploadedFiles: ref(null),
    };
  },
});
</script>

