      HORIZONTAL_SEPARATOR: formBuilderInputTypes.HORIZONTAL_SEPARATOR,
      BUTTON: formBuilderInputTypes.BUTTON,
      NOTES: formBuilderInputTypes.NOTES,
      DOCUMENT_APPROVER: formBuilderInputTypes.DOCUMENT_APPROVER,
      SECOND_APPROVER: formBuilderInputTypes.SECOND_APPROVER,
      exiting_shortcut_keys: [] as string[],
    };
  },
  watch: {
    activeFieldName(new_val: string, old_val: string) {
      if (new_val != old_val) {
        this.rowIndex = 0;
        this.columnIndex = 0;
        this.isColumnMode = false;
        this.activeComponentName = this.activeFieldName;
      }
    },

    workflow_loading(new_val: boolean, old_val: boolean) {
      if (new_val != old_val) {
        this.loadWorkflowFilteredList();
      }
    },
  },
  mounted: function () {
    this.getModelList();
    this.getLovList();
    this.initDefaults();
    this.exiting_shortcut_keys = this.fixedShortCutKeyList();

    this.activeComponentName = this.activeFieldName;

    document.addEventListener('load_settings', this.loadSettings);
    document.addEventListener('load_settings_for_series', this.loadSettingsForSeries);
  },
  unmounted: function () {
    document.removeEventListener('load_settings', this.loadSettings);
    document.removeEventListener(
      'load_settings_for_series',
      this.loadSettingsForSeries,
    );
  },
  computed: {
    activeFieldConfig() {
      return this.activeFieldName
        ? this.formBuilderConfigModel[this.activeFieldName]
        : null;
    },
  },
  methods: {
    toggleFieldHidden() {
      if (!this.activeFieldConfig) return;
      // Toggle the hidden state
      this.formBuilderConfigModel[this.activeFieldName].is_hidden = false;

      // Show success notification
      notify.success(this.$t('field_visibility_changed'), {
        description: this.$t('save_layout_to_apply_changes'),
      });
    },
    addOption() {
      const option = {
        label: 'Option',
        value: 'op',
      };
      this.formBuilderConfigModel[this.activeFieldName].options.push(option);
    },
    removeOption(itemIndex: number) {
      this.formBuilderConfigModel[this.activeFieldName].options.splice(
        itemIndex,
        1,
      );
    },
    setOptionValue(itemIndex: number) {
      this.formBuilderConfigModel[this.activeFieldName].options[
        itemIndex
      ].value = this.stringReplaceWithString(
        this.formBuilderConfigModel[this.activeFieldName].options[itemIndex]
          .label,
        ' ',
        '',
      );
    },
    loadSettings(e: any) {
      this.rowIndex = e.detail.rowIndex;
      this.columnIndex = e.detail.columnIndex;
      this.isColumnMode = e.detail.isColumnMode;
    },
    loadSettingsForSeries(e: any) {
      const columnId = e.detail;

      if (!columnId) {
        return;
      }

      for (const [index, column] of Object.entries(
        this.formBuilderConfigModel[this.activeFieldName].columns,
      )) {
        const colObj = column as any;
        if (colObj.col_id === columnId) {
          this.columnIndex = +index;
          break;
        }
      }
    },

    onFieldNameFocusLose(activeFieldName: string) {
      const fieldName = this.formBuilderConfigModel[activeFieldName].name;
      if (fieldName === this.activeComponentName) {
        return;
      }

      if (
        this.formBuilderConfigModel.hasOwnProperty(this.activeComponentName)
      ) {
        this.activeComponentName = activeFieldName;
        notify.error(this.$t('DUPLICATE_FIELD_FOUND'));
        return;
      }

      if(!this.validateField(this.activeComponentName)) {
        this.activeComponentName = fieldName;
        this.formBuilderConfigModel[activeFieldName].name = fieldName;
        return;
      }

      this.formBuilderConfigModel[fieldName].name = this.activeComponentName;

      exit_loops: for (const group of this.formLayout) {
        for (let row of group.rows) {
          if (row.name === activeFieldName) {
            // for sub groups
            if (row.fieldType == formBuilderInputTypes.SUB_GROUP) {
              row.name = this.formBuilderConfigModel[fieldName].name;
              row.label = this.formBuilderConfigModel[fieldName].label;
              row.elementWidth =
                this.formBuilderConfigModel[fieldName].elementWidth;
              break exit_loops;
            }
            // copy all other properties
            for (const [key, value] of Object.entries(
              this.formBuilderConfigModel[fieldName],
            )) {
              row[key] = value;
            }
            break exit_loops;
          }

          if (
            row.fieldType == formBuilderInputTypes.SUB_GROUP &&
            row.rows.length > 0
          ) {
            const subGroups = row.rows;

            for (let subgroup of subGroups) {
              if (subgroup.name === activeFieldName) {
                // copy all other properties
                for (const [key, value] of Object.entries(
                  this.formBuilderConfigModel[fieldName],
                )) {
                  subgroup[key] = value;
                }
                break exit_loops;
              }
            }
          }
        }
      }
      this.formBuilderConfigModel[this.activeComponentName] = {};
      this.formBuilderConfigModel[this.activeComponentName] = JSON.parse(
        JSON.stringify(this.formBuilderConfigModel[fieldName]),
      );

      this.formBuilderModel[this.activeComponentName] = {};
      this.formBuilderModel[this.activeComponentName] = JSON.parse(
        JSON.stringify(this.formBuilderModel[fieldName]),
      );

      this.activeFieldName = this.activeComponentName;
      delete this.formBuilderModel[fieldName];
      delete this.formBuilderConfigModel[fieldName];
    },

    validateField(fieldName: string) {
      let is_valid = true;
      if (fieldName === '' || fieldName === null) {
        is_valid = false;
        notify.error(this.$t('NAME_MANDATORY'));
      } else if (this.hasWhiteSpace(fieldName)) {
        is_valid = false;
        notify.error(this.$t('SPACES_NOT_ALLOWED'));
      } else if (this.checkFirstLetterIsSpecialOrNumber(fieldName)) {
        is_valid = false;
        notify.error(
          this.$t('errors_special_letter_number_not_allowed'),
        );
      }
      return is_valid;
    },

    updateFieldName(activeFieldName: string) {
      if (!this.formBuilderConfigModel[this.activeFieldName].label) {
        return;
      }

      this.activeComponentName = this.stringReplaceWithString(
        this.formBuilderConfigModel[activeFieldName].label,
        ' ',
        '_',
      );

      if (
        this.activeComponentName === activeFieldName ||
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.NOTES ||
        RESTRICTED_FIELD_APPROVER_FIELDS.includes(activeFieldName)
      ) {
        return;
      }

      this.onFieldNameFocusLose(activeFieldName);
    },
    updateColor(activeFieldName: string) {
      if (!this.formBuilderConfigModel[activeFieldName].color) {
        this.formBuilderConfigModel[activeFieldName].color =
          CONSTANTS.default_separator_color;
      }
    },
    updateSize(activeFieldName: string) {
      const size = this.formBuilderConfigModel[activeFieldName].size;
      if (!size || size < 1 || size > 10) {
        this.formBuilderConfigModel[activeFieldName].size = 2;
        notify.error(this.$t('invalid_field_length'));
      }
    },
    onTabIndexChange(tabIndex: number) {
      this.handleTabIndexChange(this.activeFieldName);
    },
    handleElementWidth(newValue: number) {
      if (newValue > 100) {
        this.formBuilderConfigModel[this.activeFieldName].elementWidth = 100;
        notify.error(this.$t('field_length_between_3_100'));
      } else if (newValue < 3) {
        this.formBuilderConfigModel[this.activeFieldName].elementWidth = 3;
        notify.error(this.$t('field_length_between_3_100'));
      }
    },
    renderModelDropdown() {
      if (
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.TEXT_INPUT ||
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.CHECK_BOX
      ) {
        return true;
      }

      return false;
    },

    onUpdateTROCRModel() {
      const fieldElement = $('#' + this.activeFieldName) as HTMLElement;

      if (fieldElement) {
        fieldElement
          .closest('.element_parent')
          ?.classList.toggle('text-primary');
      }
    },

    onColumnUpdateTROCRModel(colId: string, model: string) {
      const fieldElement = $('#col_' + colId) as HTMLElement;

      if (fieldElement) {
        if (model) {
          fieldElement.classList.add('text-primary');
        } else {
          fieldElement.classList.remove('text-primary');
        }
      }
    },

    onShortCutKeyUpdate(val: string) {
      // CHECK FOR Already Used ones
      if (val) {
        val = val.toUpperCase();
      }
      const comb_key =
        this.formBuilderConfigModel[this.activeFieldName].short_cut_key_1;
      const full_key_value = comb_key.toUpperCase() + val;

      this.formBuilderConfigModel[this.activeFieldName].error = false;
      if (!this.vaidateShortCutKey(full_key_value)) {
        this.formBuilderConfigModel[this.activeFieldName].error = true;
        this.formBuilderConfigModel[this.activeFieldName].short_cut_key_2 = '';
        return;
      }

      this.formBuilderConfigModel[this.activeFieldName].short_cut_key_2 =
        val.charAt(val.length - 1);
    },

    vaidateShortCutKey(shortcut_key: string) {
      // keyDownHelper
      if (!shortcut_key) {
        return true;
      }

      const is_used_by_other = this.isUsedByOther(shortcut_key);
      if (is_used_by_other === true) {
        return false;
      }

      if (this.exiting_shortcut_keys.indexOf(shortcut_key) === -1) {
        return true;
      }

      // validation failed
      return false;
    },

    isUsedByOther(shortcut_key: string) {
      let in_use = false;

      for (const [field_name, field] of Object.entries(
        this.formBuilderConfigModel,
      )) {
        if (field.fieldType !== 'Group' || this.activeFieldName == field_name) {
          continue;
        }

        if (shortcut_key === field.short_cut_key_2.toUpperCase()) {
          in_use = true;
        }
      }

      return in_use;
    },

    initDefaults() {
      if (!this.activeFieldConfig) return;
      const enforce_list_of_values =
        this.formBuilderConfigModel[this.activeFieldName]
          .enforce_list_of_values;
      if (!enforce_list_of_values) {
        this.formBuilderConfigModel[
          this.activeFieldName
        ].enforce_list_of_values = false;
      }
    },

    onListOfValueSelect(val: any) {
      if (!val) {
        this.formBuilderConfigModel[
          this.activeFieldName
        ].enforce_list_of_values = false;
      }
    },

    isRunScriptEnabled() {
      if (!this.activeFieldConfig) return false;
      if (
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.TEXT_INPUT ||
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.LOV_INPUT ||
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.ENUM_INPUT ||
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
          this.CHECK_BOX
      ) {
        return true;
      }

      return false;
    },

    isButtonType() {
      if (!this.activeFieldConfig) return false;
      const fieldType = this.formBuilderConfigModel[this.activeFieldName].fieldType;
      return (
        fieldType === this.EXPORT_BUTTON ||
        fieldType === this.PO_MATCH_BUTTON ||
        fieldType === this.SAVE_RULES_BUTTON ||
        fieldType === this.EXPORT_WITHOUT_VALIDATION_BUTTON ||
        fieldType === this.REJECT_DOCUMENT_BUTTON ||
        fieldType === this.BUTTON
      );
    },

    isApprovalButtonType() {
      if (!this.activeFieldConfig) return false;
      return (
        this.formBuilderConfigModel[this.activeFieldName].fieldType ===
        this.BUTTON
      );
    },

    approvalButtonTypeUpdated(val: any) {
      // on type change also update its name and label
      this.formBuilderConfigModel[this.activeFieldName].label = this.$t(
        this.formBuilderConfigModel[this.activeFieldName].type,
      );
      this.updateFieldName(
        this.formBuilderConfigModel[this.activeFieldName].name,
      );
    },

    buttonTypeUpdated(val: any) {
      if (val === 'po_match') {
        this.formBuilderConfigModel[this.activeFieldName].fieldType =
          formBuilderInputTypes.PO_MATCH_BUTTON;
      }
      if (val === 'save_rules') {
        this.formBuilderConfigModel[this.activeFieldName].fieldType =
          formBuilderInputTypes.SAVE_RULES_BUTTON;
      }
      if (val === 'export_without_validation') {
        this.formBuilderConfigModel[this.activeFieldName].fieldType =
          formBuilderInputTypes.EXPORT_WITHOUT_VALIDATION_BUTTON;
      }
      if (val === 'reject') {
        this.formBuilderConfigModel[this.activeFieldName].fieldType =
          formBuilderInputTypes.REJECT_DOCUMENT_BUTTON;
      }

      // on type change also udpate its name and label
      this.formBuilderConfigModel[this.activeFieldName].label = this.$t(
        this.formBuilderConfigModel[this.activeFieldName].exportType,
      );
      this.updateFieldName(
        this.formBuilderConfigModel[this.activeFieldName].name,
      );
    },

    loadWorkflowFilteredList() {
      this.filter_workflow_list = this.workflow_list;
    },

    filterWorkflowlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filter_workflow_list = this.workflow_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filter_workflow_list = this.workflow_list.filter(
          (v: any) => v.label.toLowerCase().startsWith(needle) as string,
        );
      });
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { handleTabIndexChange, isTabIndexField } = form_builder_store;
    const {
      activeFieldName,
      formBuilderModel,
      formBuilderConfigModel,
      formLayout,
    } = storeToRefs(form_builder_store);

    const dropdown_store = useDropdownStore();
    const { getModelList } = dropdown_store;
    const { model_list } = storeToRefs(dropdown_store);

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { getLovList } = field_values_setting_store;
    const { lov_list } = storeToRefs(field_values_setting_store);

    const workflow_store = useWorkflowsStore();
    const { workflow_loading, workflow_list } = storeToRefs(workflow_store);

    return {
      workflow_loading,
      workflow_list,
      filter_workflow_list: ref([] as any[]),

      lov_list,
      model_list,
      formLayout,
      activeFieldName,
      formBuilderModel,
      formBuilderConfigModel,
      options: prepareExportBtnOptions(),
      approvalButtonTypes: prepareApprovalBtnOptions(),
      appearanceList: [
        {
          label: 'Filled Button',
          value: '',
        },
        {
          label: 'Outline',
          value: 'secondary',
        },
        {
          label: 'Danger',
          value: 'negative-tertiary',
        },
      ],

      shortCutKeyList: [
        {
          label: 'Shift',
          value: 'shift',
        },
        {
          label: 'Alt',
          value: 'alt',
        },
      ],
      spaceFromTopList: [
        {
          label: 'None',
          value: '',
        },
        {
          label: 'Extra Small',
          value: 'q-mt-xs',
        },
        {
          label: 'Small',
          value: 'q-mt-sm',
        },
        {
          label: 'Medium',
          value: 'q-mt-md',
        },
        {
          label: 'Large',
          value: 'q-mt-lg',
        },
        {
          label: 'Extra Large',
          value: 'q-mt-xl',
        },
      ],
      spaceFromBottomList: [
        {
          label: 'None',
          value: '',
        },
        {
          label: 'Extra Small',
          value: 'q-mb-xs',
        },
        {
          label: 'Small',
          value: 'q-mb-sm',
        },
        {
          label: 'Medium',
          value: 'q-mb-md',
        },
        {
          label: 'Large',
          value: 'q-mb-lg',
        },
        {
          label: 'Extra Large',
          value: 'q-mb-xl',
        },
      ],

      // Funcation
      getLovList,
      getModelList,
      isTabIndexField,
      handleTabIndexChange,
    };
  },
});
</script>

