<template>
  <template v-if="isColumnMode">
    <div
      class="row q-pt-md"
      v-for="(tableHeaderColumn, headerColumnIndex) in formBuilderConfigModel[
        activeFieldName
      ].tableHeaderRows[rowIndex]"
      :key="headerColumnIndex"
    >
      <div class="col-sm-8 col-md-8 col-lg-8">
        <q-input
          outlined
          dense
          v-model="
            formBuilderConfigModel[activeFieldName].tableHeaderRows[rowIndex][
              headerColumnIndex
            ]
          "
        />
      </div>

      <div class="col-sm-4 col-md-4 col-lg-4">
        <q-btn
          round
          color="primary"
          icon="delete"
          size="xs"
          class="float-right"
          @click="deleteColumn(Number(headerColumnIndex))"
        >
          <q-tooltip>{{ $t('delete') }}</q-tooltip>
        </q-btn>
      </div>
    </div>
  </template>

  <template v-if="!isColumnMode">
    <div class="row q-pt-md">
      <div class="col-sm-12 col-md-12 col-lg-12 q-pa-sm mt-5">
        <div
          class="row"
          v-if="
            formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
              columnIndex
            ].isLabelArea
          "
        >
          <q-input
            class="full-width"
            outlined
            dense
            v-model="
              formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
                columnIndex
              ].label
            "
          />
        </div>

        <div class="row" v-else>
          <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
            <f-toggle
              size="xs"
              v-model="
                formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
                  columnIndex
                ].run_script_on_change
              "
              val="md"
              :label="$t('run_script_on_change')"
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
            <q-checkbox
              v-model="
                formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
                  columnIndex
                ].isDisabled
              "
              label="is Disabled ?"
            >
            </q-checkbox>
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">Tab Index</div>
          <div class="col-sm-12 col-md-12 col-lg-12">
            <q-input
              outlined
              dense
              v-model="
                formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
                  columnIndex
                ].tabIndex
              "
              type="number"
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">Field Group</div>
          <div class="col-sm-12 col-md-12 col-lg-12">
            <q-input
              outlined
              dense
              v-model="
                formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
                  columnIndex
                ].field_group
              "
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
            Field Threshold
          </div>
          <div class="col-sm-12 col-md-12 col-lg-12">
            <q-input
              outlined
              dense
              v-model="
                formBuilderConfigModel[activeFieldName].tableBodyRows[rowIndex][
                  columnIndex
                ].field_threshold
              "
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
            {{ $t('name') }}
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12">
            <q-input
              outlined
              dense
              v-model="
                formBuilderConfigModel[
                  formBuilderConfigModel[activeFieldName].tableBodyRows[
                    rowIndex
                  ][columnIndex].name
                ].name
              "
              @blur="onInputFocusLose(rowIndex, columnIndex)"
            >
            </q-input>
          </div>
        </div>
      </div>
    </div>
  </template>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';

export default defineComponent({
  name: 'PropertiesOfTableOfCheckboxes',

  props: {
    rowIndex: {
      type: Number,
      default: 0,
    },
    columnIndex: {
      type: Number,
      default: 0,
    },
    isColumnMode: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {};
  },

  methods: {
    onInputFocusLose(rowIndex: number, columnIndex: number) {
      const oldFieldName =
        this.formBuilderConfigModel[this.activeFieldName].tableBodyRows[
          this.rowIndex
        ][this.columnIndex].name;

      const updateFieldName = this.formBuilderConfigModel[oldFieldName].name;

      if (oldFieldName === updateFieldName) {
        return;
      }

      this.formBuilderConfigModel[updateFieldName] = [];
      this.formBuilderConfigModel[updateFieldName] =
        this.formBuilderConfigModel[oldFieldName];

      this.formBuilderModel[updateFieldName] = [];
      this.formBuilderModel[updateFieldName] =
        this.formBuilderModel[oldFieldName];

      delete this.formBuilderModel[oldFieldName];
      delete this.formBuilderConfigModel[oldFieldName];

      this.formBuilderConfigModel[this.activeFieldName].tableBodyRows[rowIndex][
        columnIndex
      ].name = updateFieldName;
    },
    deleteColumn(columnIndex: number) {
      this.formBuilderConfigModel[this.activeFieldName].tableHeaderRows[
        this.rowIndex
      ].tableBodyRows.splice(columnIndex, 1);

      for (let row of this.formBuilderConfigModel[this.activeFieldName]
        .tableBodyRows) {
        row.splice(columnIndex, 1);
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      activeFieldName,
      formBuilderModel,
      formBuilderConfigModel,
      formLayout,
    } = storeToRefs(form_builder_store);

    return {
      formLayout,
      activeFieldName,
      formBuilderModel,
      formBuilderConfigModel,
    };
  },
});
</script>

<style lang="scss" scoped></style>
