<template>
  <div class="image-decorator" ref="image-area" id="image_area">
    <div id="screenshot_container">
      <img
        @load="prepareImageData"
        id="screenshot"
        class="original-image"
        :src="url"
        alt="Original Image"
        v-if="url"
        :width="width"
      />
      <div v-else class="default-image-placeholder" :style="{ width: width + 'px', minHeight: '400px' }">
        <div class="placeholder-content">
          <q-icon
            name="image"
            size="4rem"
            color="grey-5"
          />
          <div class="text-grey-6 text-center q-mt-sm">{{ $t('no_image_available') }}</div>
        </div>
      </div>
      <div
        class="select-areas--overlay"
        :style="{
          opacity: opacityOverlay,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
          display: 'block',
        }"
      ></div>

      <div
        class="pointer-events-none"
        id="draw"
        :style="{
          'background-color': 'rgb(0, 0, 0)',
          opacity: 0,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
        }"
        @mousedown="mouseDown"
        @mousemove="mouseMove"
      ></div>

      <div v-for="item in areas" :key="item.id">
        <div
          @mousedown.stop.prevent="startMove(item, $event)"
          @mousemove="doMove(item, $event)"
          @click="showConnectionFromReact(item.connectionId)"
        >
          <div
            :id="
              item.areaType == 'table'
                ? item.connectionId + '_' + item.id + '_rect'
                : item.connectionId + '_rect'
            "
            class="select-areas--outline"
            :style="{
              opacity: opacityOutline,
              position: 'absolute',
              cursor: 'default',
              width: item.width + 4 + 'px',
              height: item.height + 4 + 'px',
              left: areaDisplayPosX(item) - 2 + 'px',
              top: areaDisplayPosY(item) - 2 + 'px',
              'z-index': item.z,
            }"
          ></div>
          <div
            class="select-areas--background_area"
            :style="{
              background: `#fff url('${url}') -${item.x}px -${item.y}px / ${originImgSize.w}px ${originImgSize.h}px no-repeat`,
              position: 'absolute',
              cursor: item.connectionId == connectionId ? 'move' : 'pointer',
              width: item.width + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z + 2,
            }"
            @click="changeResizable(item.id)"
          ></div>
          <div
            v-if="
              item.areaType == 'table' &&
              item.resizable &&
              item.connectionId == connectionId
            "
            class="delete-area"
            :style="{
              display: 'block',
              left: areaDisplayPosX(item) + item.width + 'px',
              top: areaDisplayPosY(item) - 25 + 'px',
              'z-index': item.z + 2,
            }"
            @click="deleteSelected(item.id)"
          >
            <div class="select-areas--delete_area"></div>
          </div>
          <!-- resize handler -->
          <Resizable
            v-if="item.connectionId == connectionId"
            :item="item"
            :posImg="posImg"
            :pos-correction="posCorrection"
            @startDrag="startDrag"
            @doDrag="doDrag"
          />
        </div>
      </div>
    </div>
    <div class="c-crop--hide_main">
      <img id="c-crop--hide_img" :src="url" alt="" :width="width" />
    </div>
  </div>
</template>
<script lang="ts">
import { storeToRefs } from 'pinia';
import { $ } from 'src/pages/assets';
import Resizable from './Resizable.vue';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore, useAuthTokenStore } from 'src/store/main';
import { notify } from 'src/components/notifications/notify';

let _this: any;
let imageArea: HTMLElement;
let screenshot: HTMLElement;

export default defineComponent({
  data() {
    return {
      mousedown: false, // state mouse down event
      originImgSize: {
        // root size image
        w: 0,
        h: 0,
        r: 0,
      },
      url: this.cropUrl,
      posImg: {
        // position box image in screen
        top: 0,
        left: 0,
      },
      areas: [
        {
          id: 1,
          x: 10,
          y: 10,
          startX: 10,
          startY: 10,
          width: 10,
          height: 10,
          z: 0,
          connectionId: '',
          areaType: 'input',
          resizable: false,
        },
      ],
      latestAreaItem: { startX: 0, startY: 0, endX: 0, endY: 0 },
      scrollLeft: 0,
      scrollTop: 0,
      moveTempX: 0,
      moveTempY: 0,
      moveCurrentX: 0,
      moveCurrentY: 0,
      temp: 0,
      dragdown: false, // state mouse event drag,
      move: false,
      imageHeight: 0,
      imageWidth: 0,
    };
  },
  props: {
    cropUrl: {
      type: String,
      // default: 'https://scontent.fhan2-3.fna.fbcdn.net/v/t1.0-9/45585072_925043081015026_6599956628924006400_o.jpg?_nc_cat=108&_nc_oc=AQlJUcFj4S_wGeX016thVhmgINU5wDV4xPBNSCIcYSti9Sm5WEPBDYO_kxK4aRP0Emo&_nc_ht=scontent.fhan2-3.fna&oh=052bb05956a1460d014205754da5a15b&oe=5DCC1053'
      default:
        'https://dev.doc2api.cloudintegration.eu/resource/image/1b90b6d5-63b5-446b-92a4-a60d57dc0edd/1.png',
    },
    width: {
      type: Number,
      default: 1500,
    },
    opacityOutline: {
      type: Number,
      default: 0.2,
    },
    opacityOverlay: {
      type: Number,
      default: 0.2,
    },
    posCorrection: {
      type: Boolean,
      default: true,
    },
    markedAreasStr: {
      type: String,
      default: '',
    },
    connectionId: {
      type: String,
      default: '',
    },
    allowMultiSelection: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    Resizable,
  },
    emits: ['restrictDrawing'],
  // created () {
  // },
  watch: {
    cropUrl(val) {
      this.url = val;
      setTimeout(() => {
        this.setSize();
      }, 200);
    },
    // send data to parent when list areas change
    // areas () {
    //   setTimeout(() => {
    //     this.getListAreas()
    //   }, 200)
    // },
    markedAreasStr(val) {
      this.prepareDataForAreas();
    },
    async width(val) {
      await this.setSize();
      this.prepareImageData();
    },
  },
  methods: {
    areaDisplayPosX(area: any): any {
      return area.x + (this.posCorrection ? this.posImg.left : 0);
    },
    areaDisplayPosY(area: any): any {
      return area.y + (this.posCorrection ? this.posImg.top : 0);
    },
    mousePosX(e: any) {
      return e.pageX - this.posImg.left;
    },
    mousePosY(e: any) {
      return e.pageY - this.posImg.top;
    },
    async setSize() {
      if (!this.url) {
        return;
      }
      let imgSize: any = await this.getSize(this.url);
      this.originImgSize = imgSize;
    },
    // Get the size of the src image
    getSize(src: any) {
      let img = this.$el.querySelector('#c-crop--hide_img');
      return new Promise((resolve) => {
        if (src && img) {
          img.onload = function () {
            // Compatible with unacceptable size
            const size = _this.getSizeImg(img);
            resolve(size);
          };
          img.src = src;
        } else {
          resolve({
            w: 0,
            h: 0,
            r: 0,
          });
        }
      });
    },
    getSizeImg(img: any) {
      let w = img.width;
      let h = img.height;
      let r = w === 0 && h === 0 ? 0 : w / h;
      return {
        w: w,
        h: h,
        r: r,
      };
    },
    calcPosOfBox() {
      // set posImg static
      let imageAreaRef: any = this.$refs['image-area'];

      this.scrollLeft =
        window.pageXOffset || document.documentElement.scrollLeft;
      this.scrollTop = window.pageYOffset || document.documentElement.scrollTop;

      let imageAreaTop = imageAreaRef.getBoundingClientRect().top;
      let imageAreaLeft = imageAreaRef.getBoundingClientRect().left;

      this.posImg.top = imageAreaTop + this.scrollTop;

      this.posImg.left = imageAreaLeft + this.scrollLeft;
    },
    // draw rectangle on image mouseDown mouseMove mouseUp
    mouseDown(e: any) {
      this.mousedown = true;
      let newAreaId = null;

      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }

      if (this.latestAreaItem.startX != 0 && this.latestAreaItem.startY != 0) {
        let startX = this.latestAreaItem.startX;
        let startY = this.latestAreaItem.startY;

        let endX = e.layerX;
        let endY = e.layerY;

        let width = endX - startX;
        let height = endY - startY;
        if (width < 0 || height < 0) {
          endX = startX;
          endY = startY;

          startX = e.layerX;
          startY = e.layerY;

          width = endX - startX;
          height = endY - startY;
        }

        let newArea = {
          id: newAreaId,
          x: startX,
          y: startY,
          startX: startX,
          startY: startY,
          width: width,
          height: height,
          z: 0,
          connectionId: this.connectionId,
          areaType: this.allowMultiSelection ? 'table' : 'input',
          resizable: false,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
        return;
      }

      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: this.mousePosX(e),
          y: this.mousePosY(e),
          startX: this.mousePosX(e),
          startY: this.mousePosY(e),
          width: 0,
          height: 0,
          z: 0,
          connectionId: this.connectionId,
          areaType: this.allowMultiSelection ? 'table' : 'input',
          resizable: false,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
        this.latestAreaItem.startX = this.mousePosX(e);
        this.latestAreaItem.startY = this.mousePosY(e);
        this.latestAreaItem.endX = 0;
        this.latestAreaItem.endY = 0;
      }
    },

    mouseMove(e: any) {
      if (this.mousedown) {
        this.areas
          .filter((x: any) => x.id === this.temp)
          .map((item: any) => {
            let x = e.pageX - this.posImg.left;
            let y = e.pageY - this.posImg.top;
            let width = item.startX - x;
            let height = item.startY - y;
            if (width < 0) {
              width *= -1;
              x -= width;
            }
            if (height < 0) {
              height *= -1;
              y -= height;
            }

            item.x = x;
            item.y = y;
            item.width = width;
            item.height = height;
          });
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
      }
    },

    mouseUp() {
      this.mousedown = false;
      // delete all point width is = 0
      this.areas = this.areas.filter(
        (item: any) => item.width >= 3 && item.height >= 3,
      );
      this.endMove();
      this.endDrag();
      this.prepareMarkedAreasList();
      if (!this.allowMultiSelection) {
        this.$emit('restrictDrawing');
      }
      // notify.success(this.$t('operation_sucessfull'));
    },

    // after click rectangle area select active resizable and dragable
    changeResizable(id: any) {
      this.areas
        .filter((item: any) => item.id === id)
        .map((item: any) => {
          item.resizable = true;
          item.z = 100;
        });
      this.areas
        .filter((item: any) => item.id !== id)
        .map((item: any) => {
          item.resizable = false;
          item.z = 0;
        });
    },

    // delete item area
    deleteSelected(id: any) {
      this.areas = this.areas.filter((item: any) => item.id !== id);
      this.prepareMarkedAreasList();
    },

    // drag point around rectangle on image startDrag doDrag endDrag
    startDrag() {
      this.dragdown = true;
    },

    doDrag(item: any, type: any, e: any) {
      if (this.dragdown) {
        switch (type) {
          case 'w':
            // fix drag outside box w position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'sw':
            // fix drag outside box sw position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = 10;
            }
            break;
          case 's':
            // fix drag outside box s position
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = 10;
            }
            break;
          case 'se':
            // fix drag outside box se position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = 10;
            }
            break;
          case 'e':
            // fix drag outside box e position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'ne':
            // fix drag outside box ne position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'n':
            // fix drag outside box n position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'nw':
            // fix drag outside box nw position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          default:
            break;
        }
      }
    },

    endDrag() {
      this.dragdown = false;
    },

    // move rectangle area startMove doMove endMove
    startMove(item: any, e: any) {
      this.move = true;

      if (item.connectionId == this.connectionId) {
        this.moveTempX = e.clientX;
        this.moveTempY = e.clientY;
        this.moveCurrentX = item.x;
        this.moveCurrentY = item.y;
      }
    },

    doMove(item: any, e: any) {
      if (item.connectionId != this.connectionId) {
        return;
      }

      if (this.move) {
        let x = this.moveCurrentX + (e.clientX - this.moveTempX);
        let y = this.moveCurrentY + (e.clientY - this.moveTempY);
        let maxX = this.originImgSize.w - item.width;
        let maxY = this.originImgSize.h - item.height;
        if (x > 0 && y > 0 && x < maxX && y < maxY) {
          item.x = x;
          item.y = y;
        }
      }
    },

    endMove() {
      this.move = false;
    },

    // this function only creats a overlay reactangle.
    creatReactangle(
      x: number,
      y: number,
      width: number,
      height: number,
      connectionId: string,
      areaType: string,
    ) {
      let newAreaId = null;
      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }
      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: x,
          y: y,
          startX: x,
          startY: y,
          width: width,
          height: height,
          z: 0,
          connectionId: connectionId,
          areaType: areaType,
          resizable: false,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
      }
    },
    prepareImageData() {
      screenshot = $('#screenshot') as HTMLElement;
      if (screenshot) {
        this.imageWidth = screenshot.offsetWidth;
        this.imageHeight = screenshot.offsetHeight;
        this.prepareDataForAreas();
      }
    },
    prepareDataForAreas() {
      this.areas = [];
      let tableRect = [];
      if (this.markedAreasList && this.markedAreasList.length > 0) {
        Array.from(this.markedAreasList).forEach((areaObj: any) => {
          tableRect = areaObj.markedArea.split(',');

          let startX = Math.round(this.imageWidth * tableRect[0]);
          let startY = Math.round(this.imageHeight * tableRect[1]);
          let endX = Math.round(this.imageWidth * tableRect[2]);
          let endY = Math.round(this.imageHeight * tableRect[3]);

          let width = endX - startX;
          let height = endY - startY;

          if (width < 0) {
            width *= -1;
            startX -= width;
          }
          if (height < 0) {
            height *= -1;
            startY -= height;
          }

          this.creatReactangle(
            startX,
            startY,
            width,
            height,
            areaObj.connectionId,
            areaObj.areaType,
          );
        });
      }
    },
    getTableAreaAsString(
      startX: number,
      startY: number,
      endX: number,
      endY: number,
    ): string {
      let x1 = startX / this.imageWidth;
      let y1 = startY / this.imageHeight;
      let x2 = endX / this.imageWidth;
      let y2 = endY / this.imageHeight;

      return (
        x1.toString() +
        ',' +
        y1.toString() +
        ',' +
        x2.toString() +
        ',' +
        y2.toString()
      );
    },
    prepareMarkedAreasList() {
      this.markedAreasList = [];
      Array.from(this.areas).forEach((data: any) => {
        let endX = data.width + data.x;
        let endY = data.height + data.y;

        this.markedAreasList.push(
          Object.assign(
            {},
            {
              markedArea: this.getTableAreaAsString(data.x, data.y, endX, endY),
              connectionId: data.connectionId,
              areaType: data.areaType,
            },
          ),
        );
      });
    },
    calculateLeftPosition(item: any): string {
      let left = this.areaDisplayPosX(item) + item.width;
      if (left + 50 >= this.imageWidth) {
        left = this.areaDisplayPosX(item) - 60;
      }
      return left + 'px';
    },
    calculatePositionFromTop(item: any): string {
      let top = this.areaDisplayPosY(item) - 25;
      if (top < 0) {
        top = this.areaDisplayPosY(item);
      }
      return top + 'px';
    },
    showConnectionFromReact(connectionId: any) {
      const event = new CustomEvent('show_connection_from_react', {
        detail: { connectionId: connectionId },
      });
      document.dispatchEvent(event);
    },
  },
  mounted() {
    _this = this;

    this.setSize();
    imageArea = $('#image_area') as HTMLElement;
    this.calcPosOfBox();

    imageArea.addEventListener('mousemove', this.calcPosOfBox);
    imageArea.addEventListener('scroll', this.calcPosOfBox);
    imageArea.addEventListener('mouseup', this.mouseUp);
  },
  unmounted: function () {
    imageArea.removeEventListener('mousemove', this.calcPosOfBox);
    imageArea.removeEventListener('scroll', this.calcPosOfBox);
    imageArea.removeEventListener('mouseup', this.mouseUp);
  },

  setup() {
    const form_builder_store = useFormBuilderStore();
    const { markedAreasList } = storeToRefs(form_builder_store);

    return {
      markedAreasList,
    };
  },
});
</script>
