import { useFormBuilderStore } from 'src/store/main';

export default {
  methods: {
    scrollToHelpSection(help_target: string) {
      const form_builder_store = useFormBuilderStore();
      form_builder_store.showInHelpSection();

      setTimeout(() => {
        try {
          const section_el: HTMLElement | null =
            document.getElementById(help_target);
          if (!section_el) {
            return;
          }
          section_el.scrollIntoView({ behavior: 'smooth' });
        } catch (e) {
          logError(e);
        }
      }, 0);
    },
  },
};
