<template>
  <f-btn
    :label="$t('auto_generate_template')"
    :loading="isAutoGenerating"
    @click="autoGenerateTemplate()"
  />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';
import { FormBuilder } from 'src/formBuilder/form_elements/formbuilder.js';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'auto-generate-default-layout',
    components: {},
  data() {
    return {
      buttonObj: ref(FormBuilder.data().buttonObj),
    };
  },
  methods: {
    autoGenerateTemplate() {
      this.isAutoGenerating = true;
      try {
        let duplicateFieldNames = [];
        let formLayoutTemp = [] as any;

        let itemMap = new Map();

        let groups = JSON.parse(JSON.stringify(this.defaultGroups));
        for (let group of groups) {
          group.elementWidth = 100;
          group.is_stcky_group = false;
          group.right_border = false;
          group.bottom_border = false;
          group.is_panel_section_group = false;

          let groupRows = [] as any;

          const groupKey = this.getGroupKey(group.name);

          if (itemMap.has(groupKey)) {
            duplicateFieldNames.push(group.name);
          }
          itemMap.set(groupKey, group.name);

          group.rows.forEach((row: any, index: any) => {
            row.forEach((subRow: any, index: any) => {
              subRow.elementWidth = 50;
              groupRows.push(subRow);

              if (itemMap.has(subRow.field_name)) {
                duplicateFieldNames.push(subRow.field_name);
              }
              itemMap.set(subRow.field_name, subRow.field_name);
            });
          });
          group.rows = [];
          group.rows = groupRows;

          if (groupRows && groupRows.length > 0) {
            formLayoutTemp.push(group);
          }
        }

        if (duplicateFieldNames && duplicateFieldNames.length > 0) {
          notify.error(
            'Duplicate key found: ' + duplicateFieldNames.join(', '),
          );
          return;
        }

        this.formBuilderModel = [];
        this.formBuilderConfigModel = [];
        this.formLayout = formLayoutTemp;

        //now add buttons at the end
        const lastItemIndex = this.formLayout.length - 1;
        let lastGroup = this.formLayout[lastItemIndex];

        if (!lastGroup.rows) {
          lastGroup.rows = [];
        }

        lastGroup.rows.push(this.prepareExportButton());
        lastGroup.rows.push(this.prepareSaveRulesButton());

        for (let field of this.defaultFields) {
          field.isAlreadyAdded = false;
        }

        // update the form
        this.reRenderGroupForm++;
      } finally {
        this.isAutoGenerating = false;
      }
    },
    prepareExportButton(): any {
      const exportButton = JSON.parse(JSON.stringify(this.buttonObj));

      exportButton.name = 'export';
      exportButton.label = 'Export';
      exportButton.text = 'Export';
      exportButton.exportType = 'export';
      exportButton.translation_key = 'export_btn';
      exportButton.fieldType = formBuilderInputTypes.EXPORT_BUTTON;

      return exportButton;
    },
    prepareSaveRulesButton(): any {
      const saveRules = JSON.parse(JSON.stringify(this.buttonObj));

      saveRules.name = 'save_rules';
      saveRules.label = 'Save Rules';
      saveRules.text = 'Save Rules';
      saveRules.exportType = 'save_rules';
      saveRules.translation_key = 'save_rules_btn';
      saveRules.fieldType = formBuilderInputTypes.SAVE_RULES_BUTTON;

      return saveRules;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { getGroupKey } = form_builder_store;
    const {
      defaultGroups,
      formLayout,
      formBuilderModel,
      formBuilderConfigModel,
      reRenderGroupForm,
      defaultFields,
      isAutoGenerating,
    } = storeToRefs(form_builder_store);

    return {
      formLayout,
      defaultFields,
      defaultGroups,
      formBuilderModel,
      reRenderGroupForm,
      formBuilderConfigModel,
      isAutoGenerating,
      getGroupKey,
    };
  },
});
</script>
